set -euo pipefail

repo_root="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
work_root="${RDF4J_CANONICAL_BENCH_WORKDIR:-${repo_root}/target/canonical-iri-benchmark}"
current_classpath_file=
format_six_classpath_file=
output_directory=
size=4096
warmups=2
repetitions=5

usage() {
    cat <<'HELP'
Usage: scripts/benchmark-canonical-iri-storage.sh [options]

By default, builds and verifies the actual 6.1.0 release, the pinned pre-change binary, and the
current implementation. Measures supported current formats 2/7, then the old format-6 binary
in a separate process for dictionary and import comparisons. Current code does not support 6.
To reuse already built, independent runtimes, supply BOTH classpath files:

  --current-classpath FILE  File containing the current jar and dependency classpath
  --format6-classpath FILE  File containing the pre-change format-6 jar and its own dependencies
  --output-dir DIRECTORY   New/empty result directory (default: timestamped under target/)
  --values N               Inputs per invocation (default: 4096)
  --warmups N              Full warmup rounds (default: 2)
  --repetitions N           Measured rounds (default: 5)

Set JAVA_HOME/PATH to the same JDK for both runtimes. Do not run concurrent builds during
measurement. RDF4J_CANONICAL_BENCH_WORKDIR and RDF4J_CANONICAL_COMPAT_WORKDIR select work directories.
HELP
}

while [[ $# -gt 0 ]]; do
    case $1 in
        --current-classpath) current_classpath_file=$2; shift 2 ;;
        --format6-classpath) format_six_classpath_file=$2; shift 2 ;;
        --output-dir) output_directory=$2; shift 2 ;;
        --values) size=$2; shift 2 ;;
        --warmups) warmups=$2; shift 2 ;;
        --repetitions) repetitions=$2; shift 2 ;;
        --help|-h) usage; exit 0 ;;
        *) usage >&2; exit 2 ;;
    esac
done

[[ ${size} =~ ^[1-9][0-9]*$ && ${warmups} =~ ^[0-9]+$ && ${repetitions} =~ ^[1-9][0-9]*$ ]] || {
    echo "Positive values/repetitions and nonnegative warmups are required." >&2
    exit 2
}
if [[ -z ${current_classpath_file} && -n ${format_six_classpath_file} ]] \
    || [[ -n ${current_classpath_file} && -z ${format_six_classpath_file} ]]; then
    echo "Supply both independent classpath files, or neither." >&2
    exit 2
fi

mkdir -p "${work_root}"
work_root="$(cd -- "${work_root}" && pwd)"
run_root="$(mktemp -d "${work_root}/run-$(date -u +%Y%m%dT%H%M%SZ)-XXXXXX")"
if [[ -z ${output_directory} ]]; then
    output_directory="${run_root}/results"
fi
mkdir -p "${output_directory}"
output_directory="$(cd -- "${output_directory}" && pwd)"
for artifact in environment.json dictionary-current-formats-2-7.csv dictionary-prechange-format-6.csv \
    imports-prechange-format-6.csv imports-canonical-format-7.csv; do
    if [[ -e ${output_directory}/${artifact} ]]; then
        echo "Refusing to replace existing benchmark evidence: ${output_directory}/${artifact}" >&2
        exit 2
    fi
done

source_verification='prebuilt classpaths supplied; producer source commit must be verified independently'
if [[ -z ${current_classpath_file} ]]; then
    compat_root="${RDF4J_CANONICAL_COMPAT_WORKDIR:-${repo_root}/target/canonical-iri-compatibility}"
    mkdir -p "${compat_root}"
    compat_root="$(cd -- "${compat_root}" && pwd)"
    export RDF4J_CANONICAL_COMPAT_WORKDIR="${compat_root}"
    "${repo_root}/scripts/verify-canonical-iri-compatibility.sh" --with-prechange-baseline
    format_six_classpath_file="${compat_root}/format-6/classpath.txt"
    source_verification='original format-6 commit checked and built by verify-canonical-iri-compatibility.sh'
    dependency_log="${run_root}/current-classpath.log"
    dependency_file="${run_root}/current-dependencies.txt"
    maven_args=(-B -ntp -Dmaven.repo.local=.m2_repo -pl core/sail/lmdb
        org.apache.maven.plugins:maven-dependency-plugin:3.8.1:build-classpath
        -DincludeScope=test "-Dmdep.outputFile=${dependency_file}")
    if ! (cd "${repo_root}" && mvn -o "${maven_args[@]}") >"${dependency_log}" 2>&1; then
        if ! rg -q 'offline mode|offline has not been downloaded|Cannot access.*offline' "${dependency_log}"; then
            tail -80 "${dependency_log}" >&2
            exit 1
        fi
        (cd "${repo_root}" && mvn "${maven_args[@]}") >"${dependency_log}" 2>&1
    fi
    current_classpath_file="${run_root}/current-input-classpath.txt"
    python3 - "${repo_root}" "${dependency_file}" "${current_classpath_file}" <<'PY'
import sys
import xml.etree.ElementTree as ET
from pathlib import Path

root, dependencies, output = map(Path, sys.argv[1:])
version = ET.parse(root / "pom.xml").getroot().find("{http://maven.apache.org/POM/4.0.0}version").text
jar = root / "core/sail/lmdb/target" / f"rdf4j-sail-lmdb-{version}.jar"
assert jar.is_file(), jar
output.write_text(str(jar) + ":" + dependencies.read_text().strip())
PY
fi

benchmark_source="${repo_root}/core/sail/lmdb/src/test/java/org/eclipse/rdf4j/sail/lmdb/CanonicalIriStorageBenchmark.java"
java_args=(-Xms512m -Xmx1g -XX:ActiveProcessorCount=2 -XX:+UseG1GC --enable-native-access=ALL-UNNAMED -ea
    "-Dlogback.configurationFile=${repo_root}/core/sail/lmdb/src/test/resources/logback-test.xml")

# Snapshot each LMDB jar before compilation and measurement. A benchmark class compiled against one CURRENT_VERSION
# is never reused for the other runtime; the benchmark also validates the selected persisted format at runtime.
python3 - "${run_root}" "${output_directory}" "${current_classpath_file}" "${format_six_classpath_file}" \
    "${source_verification}" "${size}" "${warmups}" "${repetitions}" "${benchmark_source}" <<'PY'
import hashlib
import json
import os
import platform
import shutil
import subprocess
import sys
from pathlib import Path
from zipfile import ZipFile

run, output, current, old = map(Path, sys.argv[1:5])
verification, size, warmups, repetitions, source = sys.argv[5:]
class_name = "org/eclipse/rdf4j/sail/lmdb/ValueStore.class"
producers = {}
for name, cp_file in (("current", current), ("format6", old)):
    entries = cp_file.read_text().strip().split(os.pathsep)
    jars = []
    for entry in entries:
        path = Path(entry)
        if path.is_dir() and (path / class_name).exists():
            raise SystemExit(f"Use an immutable LMDB jar instead of loose production classes: {path}")
        if path.is_file() and path.suffix == ".jar":
            with ZipFile(path) as archive:
                if class_name in archive.namelist():
                    jars.append(path)
    if len(jars) != 1:
        raise SystemExit(f"Expected one independent LMDB jar for {name}, found {jars}")
    directory = run / name
    (directory / "runner").mkdir(parents=True)
    snapshot = directory / "rdf4j-sail-lmdb.jar"
    shutil.copyfile(jars[0], snapshot)
    (directory / "dependencies.txt").write_text(os.pathsep.join(
        str(snapshot) if Path(entry) == jars[0] else entry for entry in entries))
    with ZipFile(snapshot) as archive:
        class_hash = hashlib.sha256(archive.read(class_name)).hexdigest()
    producers[name] = {
        "jar_sha256": hashlib.sha256(snapshot.read_bytes()).hexdigest(),
        "value_store_class_sha256": class_hash,
        "input_classpath_file": str(cp_file.resolve()),
    }

cpu_model = next((line.split(":", 1)[1].strip() for line in Path("/proc/cpuinfo").read_text().splitlines()
                  if line.startswith("model name")), "unavailable") if Path("/proc/cpuinfo").exists() else "unavailable"
def cgroup(name):
    path = Path("/sys/fs/cgroup") / name
    return path.read_text().strip() if path.exists() else "unavailable"

metadata = {
    "date_utc": subprocess.check_output(["date", "-u", "+%Y-%m-%dT%H:%M:%SZ"], text=True).strip(),
    "platform": platform.platform(), "cpu_model": cpu_model,
    "memory_limit_bytes": cgroup("memory.max"), "cpu_quota": cgroup("cpu.max"),
    "java": subprocess.run(["java", "-version"], text=True, stdout=subprocess.PIPE,
                           stderr=subprocess.STDOUT, check=True).stdout.strip(),
    "jvm_args": ["-Xms512m", "-Xmx1g", "-XX:ActiveProcessorCount=2", "-XX:+UseG1GC",
                 "--enable-native-access=ALL-UNNAMED", "-ea"],
    "values_per_invocation": int(size), "warmup_rounds": int(warmups), "measurement_rounds": int(repetitions),
    "case_order_seed": "0x43414e4f4e + iteration",
    "force_sync": False, "inline_literals": False, "value_overlay": False,
    "prechange_source_commit": "db572a45a401d9e7284b321efba0adbd6d577e6c",
    "supported_current_formats": [2, 7],
    "unsupported_prechange_format": 6,
    "matrix_order": ["current dictionary", "format6 dictionary", "format6 imports", "current imports"],
    "producer_source_verification": verification,
    "benchmark_source_sha256": hashlib.sha256(Path(source).read_bytes()).hexdigest(),
    "allocation_scope": "calling Java thread only; worker threads excluded",
    "cache_scope": "Java dictionary caches warm or cleared; OS cache not evicted",
    "unavailable_metric_value": -1,
    "native_probe_scope": "alternative IRI fallback native probes/seeks; dictionary_lookup_calls counts logical calls",
    "producer_jars": producers,
}
(output / "environment.json").write_text(json.dumps(metadata, indent=2) + "\n")
PY

for binary in current format6; do
    classpath="$(cat "${run_root}/${binary}/dependencies.txt")"
    javac -proc:none -cp "${classpath}" -d "${run_root}/${binary}/runner" "${benchmark_source}"
    printf '%s' "${run_root}/${binary}/runner:${classpath}" >"${run_root}/${binary}/classpath.txt"
done

run_matrix() {
    local binary=$1 mode=$2 filename=$3
    echo "Measuring ${binary} ${mode}; binary hashes and settings are in ${output_directory}/environment.json"
    java "${java_args[@]}" -cp "$(cat "${run_root}/${binary}/classpath.txt")" \
        org.eclipse.rdf4j.sail.lmdb.CanonicalIriStorageBenchmark "${mode}" \
        "${output_directory}/${filename}.csv" "${size}" "${warmups}" "${repetitions}" \
        | tee "${run_root}/${filename}.log"
}

run_matrix current dictionary dictionary-current-formats-2-7
run_matrix format6 dictionary dictionary-prechange-format-6
run_matrix format6 imports imports-prechange-format-6
run_matrix current imports imports-canonical-format-7
echo "Raw measurements: ${output_directory}"
echo "Immutable runtime jars, separately compiled harnesses, and logs: ${run_root}"
